effect.shader:
// Utility functions
vec3 rgb2hsv(vec3 c) {
    vec4 K = vec4(0.0, -1.0 / 3.0, 2.0 / 3.0, -1.0);
    vec4 p = mix(vec4(c.bg, K.wz), vec4(c.gb, K.xy), step(c.b, c.g));
    vec4 q = mix(vec4(p.xyw, c.r), vec4(c.r, p.yzx), step(p.x, c.r));

    float d = q.x - min(q.w, q.y);
    float e = 1.0e-10;
    return vec3(abs(q.z + (q.w - q.y) / (6.0 * d + e)), d / (q.x + e), q.x);
}

vec3 hsv2rgb(vec3 c) {
    vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
    vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
    return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}

// Random function for grain
float random(vec2 st) {
    return fract(sin(dot(st.xy, vec2(12.9898, 78.233))) * 43758.5453123);
}

void main() {
    vec2 uv = acScreenNorm;
    vec4 color = texture2DCv(inputImg.texture, uv);

    // Apply temperature and tint
    vec3 rgb = color.rgb;
    if (TEMPERATURE != 0.0) {
        float t = TEMPERATURE * 0.05;
        rgb.r += t;
        rgb.b -= t;
    }
    if (TINT != 0.0) {
        float t = TINT * 0.05;
        rgb.g += t;
    }

    // Apply exposure
    rgb *= pow(2.0, EXPOSURE);

    // Split into shadows, midtones, and highlights
    float luminance = dot(rgb, vec3(0.299, 0.587, 0.114));
    float shadowsMask = 1.0 - smoothstep(0.0, 0.5, luminance);
    float highlightsMask = smoothstep(0.5, 1.0, luminance);
    float midtonesMask = 1.0 - shadowsMask - highlightsMask;

    // Apply color wheel tints
    vec3 shadowsColor = mix(vec3(1.0), SHADOWS_COLOR.rgb, SHADOWS_STRENGTH);
    vec3 midtonesColor = mix(vec3(1.0), MIDTONES_COLOR.rgb, MIDTONES_STRENGTH);
    vec3 highlightsColor = mix(vec3(1.0), HIGHLIGHTS_COLOR.rgb, HIGHLIGHTS_STRENGTH);

    rgb = rgb * shadowsColor * shadowsMask + 
          rgb * midtonesColor * midtonesMask + 
          rgb * highlightsColor * highlightsMask;

    // Apply contrast
    rgb = mix(vec3(0.5), rgb, CONTRAST);

    // Convert to HSV for saturation and vibrance
    vec3 hsv = rgb2hsv(rgb);

    // Apply saturation
    hsv.y *= SATURATION;

    // Apply vibrance (saturation that protects skin tones)
    if (VIBRANCE != 0.0) {
        float sat = hsv.y;
        hsv.y = mix(sat, pow(sat, 0.25), VIBRANCE);
    }

    // Convert back to RGB
    rgb = hsv2rgb(hsv);

    // Apply film grain
    if (GRAIN > 0.0) {
        float grain = random(uv * acTime) * 2.0 - 1.0;
        rgb += grain * GRAIN;
    }

    // Apply vignette
    if (VIGNETTE > 0.0) {
        vec2 center = uv - 0.5;
        float vignette = 1.0 - dot(center, center) * 1.5 * VIGNETTE;
        rgb *= clamp(vignette, 0.0, 1.0);
    }

    // Apply fade
    if (FADE > 0.0) {
        rgb = mix(rgb, vec3(0.5, 0.5, 0.5), FADE);
    }

    gl_FragColor = vec4(rgb, color.a);
}
